      read_more: '{rasi} ಪೂರ್ಣ ರಾಶಿ ಭವಿಷ್ಯ', all_signs: 'ಇಂದಿನ 12 ರಾಶಿ ಭವಿಷ್ಯ', sign_h1: '{rasi} ರಾಶಿ ಭವಿಷ್ಯ ಇಂದು',
