      sani_good: 'ಶನಿ {rasi} ರಾಶಿಗೆ ಅನುಕೂಲ ಸ್ಥಾನದಲ್ಲಿದ್ದು ಶ್ರಮಕ್ಕೆ ತಕ್ಕ ಫಲ ನೀಡುತ್ತಾನೆ.',
      sani_mid: '{rasi} ರಾಶಿಗೆ ಶನಿ ಗೋಚಾರ ಸಾಮಾನ್ಯ; ಪ್ರಯತ್ನಕ್ಕೆ ತಕ್ಕ ಫಲ ಸಿಗುತ್ತದೆ.',
      guru_good: 'ಗುರು {rasi} ರಾಶಿಗೆ ಅನುಕೂಲ ಸ್ಥಾನದಲ್ಲಿದ್ದಾನೆ; ಶುಭಕಾರ್ಯ, ವಿದ್ಯೆ ಮತ್ತು ಪ್ರಗತಿಗೆ ಸಹಾಯಕ.',
      guru_mid: 'ಈಗ ಗುರು {rasi} ರಾಶಿಗೆ ಬಲವಾದ ಸ್ಥಾನದಲ್ಲಿಲ್ಲ; ಪ್ರಾರ್ಥನೆ ಮತ್ತು ಒಳ್ಳೆಯ ಸಲಹೆ ನೆರವಾಗುತ್ತವೆ.',
      keywords: 'ಇಂದಿನ ರಾಶಿ ಭವಿಷ್ಯ, ರಾಶಿ ಭವಿಷ್ಯ, {rasi} ರಾಶಿ ಭವಿಷ್ಯ, ದಿನ ಭವಿಷ್ಯ, ಚಂದ್ರಾಷ್ಟಮ, ರಾಹು ಕಾಲ ಇಂದು, ಇಂದಿನ ಪಂಚಾಂಗ, rashi bhavishya today',
      love_t: [['ಮನೆಯಲ್ಲಿ ಸಣ್ಣ ತಪ್ಪುಗ್ರಹಿಕೆಗಳು ಬರಬಹುದು. ಮಾತನಾಡುವುದಕ್ಕಿಂತ ಹೆಚ್ಚು ಕೇಳಿ.', 'ಇಂದು ಆತ್ಮೀಯರಿಗೆ ಸ್ವಲ್ಪ ಅವಕಾಶ ಕೊಡಿ; ಹಳೆಯ ಜಗಳಗಳನ್ನು ಕೆದಕಬೇಡಿ.'],
        ['ಕುಟುಂಬ ಜೀವನ ಸ್ಥಿರವಾಗಿರುತ್ತದೆ. ಒಟ್ಟಿಗೆ ಊಟ ಅಥವಾ ಸಣ್ಣ ಪ್ರವಾಸ ಸಂತೋಷ ನೀಡುತ್ತದೆ.', 'ಸಂಬಂಧಗಳು ಶಾಂತವಾಗಿರುತ್ತವೆ; ಇಂದು ಒಂದು ಪ್ರೀತಿಯ ಮಾತು ಬಹಳ ಕೆಲಸ ಮಾಡುತ್ತದೆ.'],
        ['ಸಂಗಾತಿ ಮತ್ತು ಕುಟುಂಬದೊಂದಿಗೆ ಮಧುರ ಕ್ಷಣಗಳು. ಮದುವೆ ಮಾತುಕತೆಗೆ ಒಳ್ಳೆಯ ದಿನ.', 'ಪ್ರೀತಿ ಮತ್ತು ಕುಟುಂಬ ಇಂದು ಸಂತೋಷ ತರುತ್ತವೆ. ಆತ್ಮೀಯರಿಗಾಗಿ ಸಮಯ ಮೀಸಲಿಡಿ.']],
      career_t: [['ಕೆಲಸ ನಿಧಾನ ಅಥವಾ ಒತ್ತಡದಂತೆ ಅನಿಸಬಹುದು. ದಿನನಿತ್ಯದ ಕೆಲಸ ಮುಗಿಸಿ, ದೊಡ್ಡ ನಿರ್ಧಾರ ಮುಂದೂಡಿ.', 'ಕಚೇರಿಯಲ್ಲಿ ವಿಳಂಬ ಸಾಧ್ಯ. ಇಮೇಲ್ ಮತ್ತು ದಾಖಲೆಗಳನ್ನು ಮತ್ತೊಮ್ಮೆ ಪರಿಶೀಲಿಸಿ.'],
        ['ಸಾಮಾನ್ಯ ಕೆಲಸದ ದಿನ. ನಿರಂತರ ಶ್ರಮ ಕೆಲಸವನ್ನು ಸರಿಯಾದ ದಾರಿಯಲ್ಲಿಡುತ್ತದೆ.', 'ಕೆಲಸ ಎಂದಿನ ವೇಗದಲ್ಲಿ ಸಾಗುತ್ತದೆ; ಮುಂದಿನ ಯೋಜನೆಗೆ ಒಳ್ಳೆಯ ದಿನ.'],
        ['ಇಂದು ನಿಮ್ಮ ಕೆಲಸ ಮಿಂಚುತ್ತದೆ. ಸಂದರ್ಶನ, ಹೊಸ ಜವಾಬ್ದಾರಿಗಳಿಗೆ ಒಳ್ಳೆಯ ದಿನ.', 'ವೃತ್ತಿ ಪ್ರಗತಿಗೆ ಬಲವಾದ ದಿನ. ಮೇಲಧಿಕಾರಿಗಳ ಬೆಂಬಲ ಸಿಗುವ ಸಾಧ್ಯತೆ.']],
      money_t: [['ಇಂದು ಖರ್ಚು ನಿಯಂತ್ರಿಸಿ; ಯಾರಿಗೂ ಸಾಲ ಕೊಡಬೇಡಿ.', 'ಹೂಡಿಕೆ ಅಥವಾ ದೊಡ್ಡ ಖರೀದಿಗೆ ಇದು ದಿನವಲ್ಲ. ಉಳಿತಾಯವನ್ನು ಕಾಪಾಡಿ.'],
        ['ಹಣದ ಹರಿವು ಸ್ಥಿರವಾಗಿರುತ್ತದೆ. ಬಜೆಟ್ ಪಾಲಿಸಿ.', 'ಆರ್ಥಿಕ ಸ್ಥಿತಿ ಸ್ಥಿರ; ಬಾಕಿ ಬಿಲ್‌ಗಳನ್ನು ಪಾವತಿಸಿ.'],
        ['ಲಾಭದ ಸಾಧ್ಯತೆ. ಬಾಕಿ ವಸೂಲಿ ಮತ್ತು ಯೋಜಿತ ಹೂಡಿಕೆಗೆ ಒಳ್ಳೆಯ ದಿನ.', 'ಹಣಕ್ಕೆ ಒಳ್ಳೆಯ ದಿನ. ನಿಂತುಹೋದ ಪಾವತಿಗಳು ಬರಬಹುದು.']],
      health_t: [['ಶಕ್ತಿ ಕಡಿಮೆಯಾಗಬಹುದು. ಚೆನ್ನಾಗಿ ವಿಶ್ರಾಂತಿ ಪಡೆದು, ಸಾಕಷ್ಟು ನೀರು ಕುಡಿದು, ಸರಳ ಆಹಾರ ಸೇವಿಸಿ.', 'ಆರೋಗ್ಯದ ಕಡೆ ಗಮನ ಕೊಡಿ; ಅತಿಯಾದ ಕೆಲಸ ಮತ್ತು ತಡರಾತ್ರಿ ಬೇಡ.'],
        ['ಆರೋಗ್ಯ ಚೆನ್ನಾಗಿರುತ್ತದೆ. ಸ್ವಲ್ಪ ನಡಿಗೆ ಅಥವಾ ಯೋಗ ಉಲ್ಲಾಸ ನೀಡುತ್ತದೆ.', 'ಸಾಮಾನ್ಯ ಆರೋಗ್ಯ; ಊಟದ ಸಮಯ ನಿಯಮಿತವಾಗಿರಲಿ.'],
        ['ಉತ್ಸಾಹ ಮತ್ತು ಚೈತನ್ಯದಿಂದ ಇರುತ್ತೀರಿ. ವ್ಯಾಯಾಮ ಆರಂಭಿಸಲು ಒಳ್ಳೆಯ ದಿನ.', 'ಒಳ್ಳೆಯ ಆರೋಗ್ಯ ಮತ್ತು ಸ್ಪಷ್ಟ ಮನಸ್ಸು ಇಂದು ಬಹಳ ಕೆಲಸ ಮುಗಿಸಲು ನೆರವಾಗುತ್ತವೆ.']],
      remedy_t: ['ಸೂರ್ಯೋದಯದಲ್ಲಿ ಸೂರ್ಯನಿಗೆ ಅರ್ಘ್ಯ ನೀಡಿ ಗಾಯತ್ರಿ ಮಂತ್ರ ಜಪಿಸಿ.', 'ಶಿವನನ್ನು ಪೂಜಿಸಿ ಶಿವಲಿಂಗಕ್ಕೆ ನೀರು ಅಥವಾ ಹಾಲಿನ ಅಭಿಷೇಕ ಮಾಡಿ.',
        'ಆಂಜನೇಯ ಅಥವಾ ಸುಬ್ರಹ್ಮಣ್ಯ ಸ್ವಾಮಿಯನ್ನು ಪೂಜಿಸಿ ಕೆಂಪು ಹೂ ಅರ್ಪಿಸಿ.', 'ಗಣಪತಿಯನ್ನು ಪೂಜಿಸಿ ಗರಿಕೆ ಅರ್ಪಿಸಿ.',
        'ಗುರು ರಾಘವೇಂದ್ರ ಅಥವಾ ದತ್ತಾತ್ರೇಯರನ್ನು ಪೂಜಿಸಿ ಹಳದಿ ಹೂ ಅರ್ಪಿಸಿ.', 'ಲಕ್ಷ್ಮೀದೇವಿಯನ್ನು ಪೂಜಿಸಿ ಸಂಜೆ ತುಪ್ಪದ ದೀಪ ಹಚ್ಚಿ.',
        'ಶನಿದೇವರಿಗೆ ಎಳ್ಳೆಣ್ಣೆ ದೀಪ ಹಚ್ಚಿ, ಅಗತ್ಯವಿರುವವರಿಗೆ ಸಹಾಯ ಮಾಡಿ.'],
      vrat: { ekadashi: ['ಏಕಾದಶಿ', 'ಉಪವಾಸ ಮಾಡಿ ವಿಷ್ಣುವನ್ನು ಪೂಜಿಸುವ ದಿನ.'], pradosham: ['ಪ್ರದೋಷ', 'ಸಂಜೆ ಪ್ರದೋಷ ಕಾಲದಲ್ಲಿ ಶಿವಪೂಜೆ ಮನಶ್ಶಾಂತಿ ನೀಡುತ್ತದೆ.'],
        pournami: ['ಹುಣ್ಣಿಮೆ', 'ಸತ್ಯನಾರಾಯಣ ಪೂಜೆ ಮತ್ತು ದಾನಕ್ಕೆ ಶುಭ ದಿನ.'], amavasya: ['ಅಮಾವಾಸ್ಯೆ', 'ಪಿತೃಗಳಿಗೆ ತರ್ಪಣ ನೀಡಿ ಸ್ಮರಿಸುವ ದಿನ.'],
        sankashti: ['ಸಂಕಷ್ಟಹರ ಚತುರ್ಥಿ', 'ಗಣಪತಿಗೆ ವ್ರತ; ಚಂದ್ರೋದಯದ ನಂತರ ವ್ರತ ಮುಗಿಸಿ.'], chaturthi: ['ವಿನಾಯಕ ಚತುರ್ಥಿ (ಮಾಸಿಕ)', 'ಗಣಪತಿಯ ಮಾಸಿಕ ದಿನ; ಹೊಸ ಆರಂಭಕ್ಕೆ ಒಳ್ಳೆಯದು.'],
        shashti: ['ಷಷ್ಠಿ', 'ಸುಬ್ರಹ್ಮಣ್ಯ ಸ್ವಾಮಿಯ ಪೂಜೆ ಮತ್ತು ಮಕ್ಕಳ ಒಳಿತಿಗಾಗಿ ವ್ರತದ ದಿನ.'], ashtami: ['ಕಾಲಾಷ್ಟಮಿ', 'ರಕ್ಷಣೆಗಾಗಿ ಕಾಲಭೈರವನನ್ನು ಪೂಜಿಸುವ ದಿನ.'],
        sankranti: ['{rasi} ಸಂಕ್ರಾಂತಿ', 'ಇಂದು ಸೂರ್ಯ {rasi} ರಾಶಿಗೆ ಪ್ರವೇಶಿಸುತ್ತಾನೆ; ಹೊಸ ಸೌರ ಮಾಸ ಆರಂಭ.'] }
